0001 | static void coroutine_fn mirror_wait_on_conflicts(MirrorOp *self,
0002 | MirrorBlockJob *s,
0003 | uint64_t offset,
0004 | uint64_t bytes)
0005 | {
0006 | uint64_t self_start_chunk = offset / s->granularity;
0007 | uint64_t self_end_chunk = DIV_ROUND_UP(offset + bytes, s->granularity);
0008 | uint64_t self_nb_chunks = self_end_chunk - self_start_chunk;
0009 | while (find_next_bit(s->in_flight_bitmap, self_end_chunk,
0010 | self_start_chunk) < self_end_chunk &&
0011 | s->ret >= 0)
0012 | {
0013 | MirrorOp *op;
0014 | QTAILQ_FOREACH(op, &s->ops_in_flight, next) {
0015 | uint64_t op_start_chunk = op->offset / s->granularity;
0016 | uint64_t op_nb_chunks = DIV_ROUND_UP(op->offset + op->bytes,
0017 | s->granularity) -
0018 | op_start_chunk;
0019 | if (op == self) {
0020 | continue;
0021 | }
0022 | if (ranges_overlap(self_start_chunk, self_nb_chunks,
0023 | op_start_chunk, op_nb_chunks))
