0022 | if( diff_Q15 < min_diff_Q15 ) {
0023 | min_diff_Q15 = diff_Q15;
0024 | I = L;
0025 | }
0026 | if( min_diff_Q15 >= 0 ) {
0027 | return;
0028 | }
0029 | if( I == 0 ) {
0030 | NLSF_Q15[0] = NDeltaMin_Q15[0];
0031 | } else if( I == L) {
0032 | NLSF_Q15[L-1] = ( 1 << 15 ) - NDeltaMin_Q15[L];
0033 | } else {
0034 | min_center_Q15 = 0;
0035 | for( k = 0; k < I; k++ ) {
0036 | min_center_Q15 += NDeltaMin_Q15[k];
0037 | }
0038 | min_center_Q15 += silk_RSHIFT( NDeltaMin_Q15[I], 1 );
0039 | max_center_Q15 = 1 << 15;
