0001 | static int check_passwd(unsigned char *passwd, size_t length)
0002 | {
0003 | struct digest *d = NULL;
0004 | unsigned char *passwd1_sum;
0005 | unsigned char *passwd2_sum;
0006 | int ret = 0;
0007 | int hash_len;
0008 | if (IS_ENABLED(CONFIG_PASSWD_CRYPTO_PBKDF2)) {
0009 | hash_len = PBKDF2_LENGTH;
0010 | } else {
0011 | d = digest_alloc(PASSWD_SUM);
0012 | if (!d) {
0013 | pr_err("No such digest: %s\n",
0014 | PASSWD_SUM ? PASSWD_SUM : "NULL");
0015 | return -ENOENT;
0016 | }
0017 | hash_len = digest_length(d);
0018 | }
0019 | passwd1_sum = calloc(hash_len * 2, sizeof(unsigned char));
0020 | if (!passwd1_sum)
0021 | return -ENOMEM;
0022 | passwd2_sum = passwd1_sum + hash_len;
0023 | if (is_passwd_env_enable())
0024 | ret = read_env_passwd(passwd2_sum, hash_len);
0025 | else if (is_passwd_default_enable())
0026 | ret = read_default_passwd(passwd2_sum, hash_len);
0027 | else
0028 | ret = -EINVAL;
0029 | if (ret < 0)
0030 | goto err;
0031 | if (IS_ENABLED(CONFIG_PASSWD_CRYPTO_PBKDF2)) {
0032 | char *key = passwd2_sum + PBKDF2_SALT_LEN;
0033 | char *salt = passwd2_sum;
0034 | int keylen = PBKDF2_LENGTH - PBKDF2_SALT_LEN;
0035 | ret = pkcs5_pbkdf2_hmac_sha1(passwd, length, salt,
0036 | PBKDF2_SALT_LEN, PBKDF2_COUNT, keylen, passwd1_sum);
0037 | if (ret)
0038 | goto err;
0039 | if (strncmp(passwd1_sum, key, keylen) == 0)
0040 | ret = 1;
0041 | } else {
0042 | ret = digest_digest(d, passwd, length, passwd1_sum);
0043 | if (ret)
0044 | goto err;
0045 | if (strncmp(passwd1_sum, passwd2_sum, hash_len) == 0)
0046 | ret = 1;
0047 | }
0048 | err:
0049 | free(passwd1_sum);
0050 | digest_free(d);
0051 | return ret;
0052 | }

