0001 | static int
0002 | token_continue(i_ctx_t *i_ctx_p, scanner_state * pstate, bool save)
0003 | {
0004 | os_ptr op = osp;
0005 | int code;
0006 | ref token;
0007 | pop(1);                     
0008 | again:
0009 | code = gs_scan_token(i_ctx_p, &token, pstate);
0010 | op = osp;
0011 | switch (code) {
0012 | default:                
0013 | if (code > 0)       
0014 | code = gs_note_error(gs_error_syntaxerror);
0015 | gs_scanner_error_object(i_ctx_p, pstate, &i_ctx_p->error_object);
0016 | break;
0017 | case scan_BOS:
0018 | code = 0;
0019 | case 0:         
0020 | push(2);
0021 | ref_assign(op - 1, &token);
0022 | make_true(op);
0023 | break;
0024 | case scan_EOF:          
0025 | push(1);
0026 | make_false(op);
0027 | code = 0;
0028 | break;
0029 | case scan_Refill:       
0030 | code = gs_scan_handle_refill(i_ctx_p, pstate, save,
0031 | ztoken_continue);
0032 | switch (code) {
0033 | case 0: 
0034 | goto again;
0035 | case o_push_estack:
0036 | return code;
0037 | }
0038 | break;              
0039 | }
0040 | if (code <= 0 && !save) {   
0041 | ifree_object(pstate, "token_continue");
0042 | }
0043 | return code;
0044 | }

