0056 | dense_t->shaped<T, NDIM>(b.y_reshape())                                \
0057 | .broadcast(BCast::ToIndexArray<NDIM>(b.y_bcast()));                \
0058 | Eigen::array<Eigen::DenseIndex, NDIM> idx;                                 \
0059 | bool indices_valid = true;                                                 \
0060 | for (int i = 0; i < nnz; ++i) {                                            \
