0001 | static void __release_mid(struct kref *refcount)
0002 | {
0003 | struct mid_q_entry *midEntry =
0004 | container_of(refcount, struct mid_q_entry, refcount);
0005 | #ifdef CONFIG_CIFS_STATS2
0006 | __le16 command = midEntry->server->vals->lock_cmd;
0007 | __u16 smb_cmd = le16_to_cpu(midEntry->command);
0008 | unsigned long now;
0009 | unsigned long roundtrip_time;
0010 | #endif
0011 | struct TCP_Server_Info *server = midEntry->server;
0012 | if (midEntry->resp_buf && (midEntry->mid_flags & MID_WAIT_CANCELLED) &&
0013 | midEntry->mid_state == MID_RESPONSE_RECEIVED &&
0014 | server->ops->handle_cancelled_mid)
0015 | server->ops->handle_cancelled_mid(midEntry, server);
0016 | midEntry->mid_state = MID_FREE;
