0025 | cifs_server_dbg(VFS, "Invalid mid allocation time\n");
0026 | roundtrip_time = now - midEntry->when_alloc;
0027 | if (smb_cmd < NUMBER_OF_SMB2_COMMANDS) {
0028 | if (atomic_read(&server->num_cmds[smb_cmd]) == 0) {
0029 | server->slowest_cmd[smb_cmd] = roundtrip_time;
0030 | server->fastest_cmd[smb_cmd] = roundtrip_time;
0031 | } else {
0032 | if (server->slowest_cmd[smb_cmd] < roundtrip_time)
0033 | server->slowest_cmd[smb_cmd] = roundtrip_time;
0034 | else if (server->fastest_cmd[smb_cmd] > roundtrip_time)
0035 | server->fastest_cmd[smb_cmd] = roundtrip_time;
0036 | }
0037 | cifs_stats_inc(&server->num_cmds[smb_cmd]);
0038 | server->time_per_cmd[smb_cmd] += roundtrip_time;
0039 | }
