0016 | addr = dma_map_single(&ndev->dev, (void *)skb->data, len,
0017 | DMA_TO_DEVICE);
0018 | if (unlikely(dma_mapping_error(&ndev->dev, addr))) {
0019 | stats->tx_dropped++;
0020 | stats->tx_errors++;
0021 | dev_kfree_skb(skb);
0022 | return NETDEV_TX_OK;
0023 | }
