0001 | Status ConcatShapeHelper(InferenceContext* c, int start_value_index,
0002 | int end_value_index, int dim_index) {
0003 | ShapeHandle unused;
0004 | TF_RETURN_IF_ERROR(c->WithRank(c->input(dim_index), 0, &unused));
0005 | const Tensor* concat_dim_t = c->input_tensor(dim_index);
0006 | if (concat_dim_t == nullptr) {
0007 | int32_t rank = InferenceContext::kUnknownRank;
0008 | for (int i = start_value_index; i < end_value_index; ++i) {
0009 | if (rank == InferenceContext::kUnknownRank) rank = c->Rank(c->input(i));
0010 | if (rank != InferenceContext::kUnknownRank) {
0011 | break;
0012 | }
0013 | }
0014 | if (rank == InferenceContext::kUnknownRank) {
0015 | c->set_output(0, c->UnknownShape());
0016 | return Status::OK();
0017 | } else if (rank == 0) {
0018 | return errors::InvalidArgument(
0019 | "Can't concatenate scalars (use tf.stack instead)");
0020 | } else {
0021 | for (int i = start_value_index; i < end_value_index; ++i) {
0022 | TF_RETURN_IF_ERROR(c->WithRank(c->input(i), rank, &unused));
0023 | }
0024 | }
0025 | std::vector<DimensionHandle> dims;
0026 | dims.reserve(rank);
0027 | for (int i = 0; i < rank; ++i) dims.push_back(c->UnknownDim());
0028 | c->set_output(0, c->MakeShape(dims));
0029 | return Status::OK();
0030 | }
0031 | int64_t concat_dim;
0032 | if (concat_dim_t->dtype() == DT_INT32) {
0033 | concat_dim = static_cast<int64_t>(concat_dim_t->flat<int32>()(0));
0034 | } else {
0035 | concat_dim = concat_dim_t->flat<int64_t>()(0);
0036 | }
0037 | const int min_rank = concat_dim < 0 ? -concat_dim : concat_dim + 1;
0038 | ShapeHandle output_before;
0039 | ShapeHandle output_after;
0040 | ShapeHandle input = c->input(end_value_index - 1);
0041 | TF_RETURN_IF_ERROR(c->WithRankAtLeast(input, min_rank, &input));
0042 | TF_RETURN_IF_ERROR(c->Subshape(input, 0, concat_dim, &output_before));
0043 | DimensionHandle output_middle = c->Dim(input, concat_dim);
0044 | if (concat_dim == -1) {
0045 | output_after = c->Scalar();    } else {
0046 | TF_RETURN_IF_ERROR(c->Subshape(input, concat_dim + 1, &output_after));
0047 | }
0048 | for (int i = end_value_index - 2; i >= start_value_index; --i) {
0049 | ShapeHandle before;
0050 | ShapeHandle after;
0051 | input = c->input(i);
0052 | TF_RETURN_IF_ERROR(c->WithRankAtLeast(input, min_rank, &input));
0053 | TF_RETURN_IF_ERROR(c->Subshape(input, 0, concat_dim, &before));
0054 | DimensionHandle middle = c->Dim(input, concat_dim);
0055 | if (concat_dim == -1) {
0056 | after = c->Scalar();
0057 | } else {
0058 | TF_RETURN_IF_ERROR(c->Subshape(input, concat_dim + 1, &after));
0059 | }
0060 | TF_RETURN_IF_ERROR(c->Merge(before, output_before, &output_before));
0061 | TF_RETURN_IF_ERROR(c->Add(output_middle, middle, &output_middle));
0062 | TF_RETURN_IF_ERROR(c->Merge(after, output_after, &output_after));
0063 | }
0064 | ShapeHandle s;
0065 | TF_RETURN_IF_ERROR(
0066 | c->Concatenate(output_before, c->Vector(output_middle), &s));
0067 | TF_RETURN_IF_ERROR(c->Concatenate(s, output_after, &s));
0068 | c->set_output(0, s);
0069 | return Status::OK();
0070 | }

