0001 | MOBI_RET mobi_parse_huffdic(const MOBIData *m, MOBIHuffCdic *huffcdic) {
0002 | MOBI_RET ret;
0003 | const size_t offset = mobi_get_kf8offset(m);
0004 | if (m->mh == NULL || m->mh->huff_rec_index == NULL || m->mh->huff_rec_count == NULL) {
0005 | debug_print("%s", "HUFF/CDIC records metadata not found in MOBI header\n");
0006 | return MOBI_DATA_CORRUPT;
0007 | }
0008 | const size_t huff_rec_index = *m->mh->huff_rec_index + offset;
0009 | const size_t huff_rec_count = *m->mh->huff_rec_count;
0010 | if (huff_rec_count > HUFF_RECORD_MAXCNT) {
0011 | debug_print("Too many HUFF record (%zu)\n", huff_rec_count);
0012 | return MOBI_DATA_CORRUPT;
0013 | }
0014 | const MOBIPdbRecord *curr = mobi_get_record_by_seqnumber(m, huff_rec_index);
0015 | if (curr == NULL || huff_rec_count < 2) {
0016 | debug_print("%s", "HUFF/CDIC record not found\n");
0017 | return MOBI_DATA_CORRUPT;
0018 | }
0019 | if (curr->size < HUFF_RECORD_MINSIZE) {
0020 | debug_print("HUFF record too short (%zu b)\n", curr->size);
0021 | return MOBI_DATA_CORRUPT;
0022 | }
0023 | ret = mobi_parse_huff(huffcdic, curr);
0024 | if (ret != MOBI_SUCCESS) {
0025 | debug_print("%s", "HUFF parsing failed\n");
0026 | return ret;
0027 | }
0028 | curr = curr->next;
0029 | huffcdic->symbols = malloc((huff_rec_count - 1) * sizeof(*huffcdic->symbols));
0030 | if (huffcdic->symbols == NULL) {
0031 | debug_print("%s\n", "Memory allocation failed");
0032 | return MOBI_MALLOC_FAILED;
0033 | }
0034 | size_t i = 0;
0035 | while (i < huff_rec_count - 1) {
0036 | if (curr == NULL) {
0037 | debug_print("%s\n", "CDIC record not found");
0038 | return MOBI_DATA_CORRUPT;
0039 | }
0040 | ret = mobi_parse_cdic(huffcdic, curr, i++);
0041 | if (ret != MOBI_SUCCESS) {
0042 | debug_print("%s", "CDIC parsing failed\n");
0043 | return ret;
0044 | }
0045 | curr = curr->next;
0046 | }
0047 | return MOBI_SUCCESS;
0048 | }

