0001 | static int do_sched_cfs_period_timer(struct cfs_bandwidth *cfs_b, int overrun, unsigned long flags)
0002 | {
0003 | u64 runtime, runtime_expires;
0004 | int throttled;
0005 | if (cfs_b->quota == RUNTIME_INF)
0006 | goto out_deactivate;
0007 | throttled = !list_empty(&cfs_b->throttled_cfs_rq);
0008 | cfs_b->nr_periods += overrun;
