0010 | goto out_deactivate;
0011 | __refill_cfs_bandwidth_runtime(cfs_b);
0012 | if (!throttled) {
0013 | cfs_b->idle = 1;
0014 | return 0;
0015 | }
0016 | cfs_b->nr_throttled += overrun;
0017 | runtime_expires = cfs_b->runtime_expires;
0018 | while (throttled && cfs_b->runtime > 0 && !cfs_b->distribute_running) {
0019 | runtime = cfs_b->runtime;
0020 | cfs_b->distribute_running = 1;
0021 | raw_spin_unlock_irqrestore(&cfs_b->lock, flags);
0022 | runtime = distribute_cfs_runtime(cfs_b, runtime,
