0024 | raw_spin_lock_irqsave(&cfs_b->lock, flags);
0025 | cfs_b->distribute_running = 0;
0026 | throttled = !list_empty(&cfs_b->throttled_cfs_rq);
0027 | lsub_positive(&cfs_b->runtime, runtime);
0028 | }
