0001 | void yajl_string_decode(yajl_buf buf, const unsigned char * str,
0002 | unsigned int len)
0003 | {
0004 | unsigned int beg = 0;
0005 | unsigned int end = 0;    
0006 | while (end < len) {
0007 | if (str[end] == '\\') {
0008 | char utf8Buf[5];
0009 | const char * unescaped = "?";
0010 | yajl_buf_append(buf, str + beg, end - beg);
0011 | switch (str[++end]) {
0012 | case 'r': unescaped = "\r"; break;
0013 | case 'n': unescaped = "\n"; break;
0014 | case '\\': unescaped = "\\"; break;
0015 | case '/': unescaped = "/"; break;
0016 | case '"': unescaped = "\""; break;
0017 | case 'f': unescaped = "\f"; break;
0018 | case 'b': unescaped = "\b"; break;
0019 | case 't': unescaped = "\t"; break;
0020 | case 'u': {
0021 | unsigned int codepoint = 0;
0022 | hexToDigit(&codepoint, str + ++end);
0023 | end+=3;
0024 | if ((codepoint & 0xFC00) == 0xD800) {
0025 | end++;
0026 | if (str[end] == '\\' && str[end + 1] == 'u') {
0027 | unsigned int surrogate = 0;
0028 | hexToDigit(&surrogate, str + end + 2);
0029 | codepoint =
0030 | (((codepoint & 0x3F) << 10) | 
0031 | ((((codepoint >> 6) & 0xF) + 1) << 16) | 
0032 | (surrogate & 0x3FF));
0033 | end += 5;
0034 | } else {
0035 | unescaped = "?";
0036 | break;
0037 | }
0038 | }
