0036 | type = zfp_type_double;
0037 | break;
0038 | default:
0039 | free(shape);
0040 | free(chunkshape);
0041 | free(blockshape);
0042 | BLOSC_TRACE_ERROR("ZFP is not available for typesize: %d", typesize);
0043 | return BLOSC2_ERROR_FAILURE;
0044 | }
0045 | zfp = zfp_stream_open(NULL);
