0052 | field = zfp_field_1d((void *) output, type, blockshape[0]);
0053 | break;
0054 | case 2:
0055 | field = zfp_field_2d((void *) output, type, blockshape[1], blockshape[0]);
0056 | break;
0057 | case 3:
0058 | field = zfp_field_3d((void *) output, type, blockshape[2], blockshape[1], blockshape[0]);
0059 | break;
0060 | case 4:
0061 | field = zfp_field_4d((void *) output, type, blockshape[3], blockshape[2], blockshape[1], blockshape[0]);
0062 | break;
0063 | default:
0064 | free(shape);
0065 | free(chunkshape);
0066 | free(blockshape);
0067 | BLOSC_TRACE_ERROR("ZFP is not available for ndims: %d", ndim);
