0001 | static inline int
0002 | get_maptrack_handle(
0003 | struct grant_table *lgt)
0004 | {
0005 | struct vcpu          *curr = current;
0006 | int                   i;
0007 | grant_handle_t        handle;
0008 | struct grant_mapping *new_mt;
0009 | handle = __get_maptrack_handle(lgt, curr);
0010 | if ( likely(handle != -1) )
0011 | return handle;
0012 | spin_lock(&lgt->maptrack_lock);
0013 | if ( nr_maptrack_frames(lgt) >= max_maptrack_frames )
0014 | {
0015 | spin_unlock(&lgt->maptrack_lock);
0016 | if ( curr->maptrack_tail == MAPTRACK_TAIL )
0017 | {
0018 | handle = steal_maptrack_handle(lgt, curr);
0019 | if ( handle == -1 )
0020 | return -1;
0021 | curr->maptrack_tail = handle;
0022 | write_atomic(&curr->maptrack_head, handle);
0023 | }
0024 | return steal_maptrack_handle(lgt, curr);
0025 | }
0026 | new_mt = alloc_xenheap_page();
0027 | if ( !new_mt )
0028 | {
0029 | spin_unlock(&lgt->maptrack_lock);
0030 | return -1;
0031 | }
0032 | clear_page(new_mt);
0033 | handle = lgt->maptrack_limit;
0034 | for ( i = 0; i < MAPTRACK_PER_PAGE; i++ )
0035 | {
0036 | new_mt[i].ref = handle + i + 1;
0037 | new_mt[i].vcpu = curr->vcpu_id;
0038 | }
0039 | new_mt[i - 1].ref = curr->maptrack_head;
0040 | if ( curr->maptrack_tail == MAPTRACK_TAIL )
0041 | curr->maptrack_tail = handle + MAPTRACK_PER_PAGE - 1;
0042 | write_atomic(&curr->maptrack_head, handle + 1);
0043 | lgt->maptrack[nr_maptrack_frames(lgt)] = new_mt;
0044 | lgt->maptrack_limit += MAPTRACK_PER_PAGE;
0045 | spin_unlock(&lgt->maptrack_lock);
0046 | return handle;
0047 | }

